/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  var D = {"anc": [[140, 60], [250, 60], [140, 215], [250, 215]], "ys": [50.0, 110.0, 170.0, 230.0], "RX": 344, "LX": 6, "TW": 74};
  phases([[0,22],[22,40],[40,66],[66,86]]);
  var nd = 0;
  for (var i = 0; i < 2; i++) { v['dm'+i] = lin([[4 + i * 7, 0],[7 + i * 7, 1]]) * out; if (p >= 6 + i * 7) nd += 2; }
  v.nd = nd; v.il = lin([[24,0],[30,1]]) * out; v.ni = p >= 28 ? 3 : 0;
  var sw = lin([[70,0],[76,1]]);
  v.sRight = (p >= 42 && p < 70) ? 1 : 0; v.sLeft = (p >= 70 && p < 97) ? 1 : 0; v.sTop = 0; v.sBottom = 0;
  var nt = 0;
  for (var i = 0; i < D.anc.length; i++) {
    var t = 43 + i * 2.2, f = lin([[t,0],[t+1.5,1]]); if (p >= t + 1) nt++;
    var tx = D.RX + (D.LX - D.RX) * sw, ty = D.ys[i];
    v['tg'+i] = 'opacity: ' + ((f > 0.01 ? 1 : 0) * out) + '; transform: translate(' + tx.toFixed(1) + 'px,' + ty.toFixed(1) + 'px);';
    v['to'+i] = (f > 0.01 ? f : 0) * out;
    var ax = D.anc[i][0], ay = D.anc[i][1], sx = (sw < 0.5) ? tx : tx + D.TW, ex = sx + (sw < 0.5 ? -12 : 12);
    v['ld'+i] = 'M' + sx.toFixed(1) + ',' + ty.toFixed(1) + 'H' + ex.toFixed(1) + 'L' + ax.toFixed(1) + ',' + ay.toFixed(1);
    var dx = ax - ex, dy = ay - ty, L = Math.sqrt(dx*dx + dy*dy) || 1, ux = dx / L, uy = dy / L, bx = ax - ux * 7, by = ay - uy * 7;
    v['ah'+i] = 'M' + ax.toFixed(1) + ',' + ay.toFixed(1) + 'L' + (bx - uy * 2.6).toFixed(1) + ',' + (by + ux * 2.6).toFixed(1) + 'L' + (bx + uy * 2.6).toFixed(1) + ',' + (by - ux * 2.6).toFixed(1) + 'Z';
  }
  v.nt = nt;
  v.fin = (p >= 78 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
